            userRecord = existingUserByEmail
            userId = userRecord.userId

            // Create OAuth account link
            ec.entity.makeValue("novel.anime.user.UserOAuthAccount").setAll([
                oauthAccountId: ec.entity.sequencedIdPrimary,
                userId: userId,
                provider: "github",
                providerUserId: githubUserId,
                accessToken: githubAccessToken,
                profileData: profileData,
                createdDate: now,
                lastUsedDate: now
            ]).create()

            // Update user's last login and avatar if not set
            userRecord.lastLoginDate = now
            if (avatarUrl &amp;&amp; !userRecord.avatarUrl) {
                userRecord.avatarUrl = avatarUrl
            }
            // Update authProvider if it was 'local'
            if (userRecord.authProvider == 'local') {
                userRecord.authProvider = 'github'
            }
            userRecord.update()

            ec.logger.info("GitHub account linked to existing user: ${email}")

        } else {
