import java.net.http.HttpClient import java.net.http.HttpRequest import java.net.http.HttpResponse import java.net.URI import java.nio.charset.StandardCharsets import groovy.json.JsonSlurper import groovy.json.JsonBuilder
try { // Get OAuth configuration def clientId = System.getenv("GOOGLE_CLIENT_ID") ?: "your_google_client_id" def clientSecret = System.getenv("GOOGLE_CLIENT_SECRET") ?: "your_google_client_secret" def callbackUrl = System.getenv("GOOGLE_CALLBACK_URL") ?: "http://localhost:8080/rest/s1/novel-anime/auth/oauth/google/callback" def tokenUrl = "https://oauth2.googleapis.com/token" def apiUrl = "https://www.googleapis.com/oauth2/v2/userinfo"
// Validate configuration if (clientId == "your_google_client_id" || clientSecret == "your_google_client_secret") { success = false message = "Google OAuth is not configured. Please set GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET environment variables." errorCode = "OAUTH_NOT_CONFIGURED" return }
// Step 1: Exchange authorization code for access token def httpClient = HttpClient.newBuilder() .version(HttpClient.Version.HTTP_2) .build()
def tokenRequestBody = [ "client_id=${clientId}", "client_secret=${clientSecret}", "code=${code}", "grant_type=authorization_code", "redirect_uri=${callbackUrl}" ].join("&")
def tokenRequest = HttpRequest.newBuilder() .uri(URI.create(tokenUrl)) .header("Content-Type", "application/x-www-form-urlencoded") .header("Accept", "application/json") .POST(HttpRequest.BodyPublishers.ofString(tokenRequestBody)) .build()
def tokenResponse = httpClient.send(tokenRequest, HttpResponse.BodyHandlers.ofString())
if (tokenResponse.statusCode() != 200) { ec.logger.error("Google token exchange failed: ${tokenResponse.body()}") success = false message = "Failed to exchange authorization code. Please try again." errorCode = "TOKEN_EXCHANGE_FAILED" return }
def tokenData = new JsonSlurper().parseText(tokenResponse.body())
if (tokenData.error) { ec.logger.error("Google OAuth error: ${tokenData.error_description ?: tokenData.error}") success = false message = tokenData.error_description ?: "Google authorization failed." errorCode = "GOOGLE_AUTH_ERROR" return }
def googleAccessToken = tokenData.access_token if (!googleAccessToken) { success = false message = "No access token received from Google." errorCode = "NO_ACCESS_TOKEN" return }
// Step 2: Fetch user profile from Google API def userRequest = HttpRequest.newBuilder() .uri(URI.create(apiUrl)) .header("Authorization", "Bearer ${googleAccessToken}") .header("Accept", "application/json") .GET() .build()
def userResponse = httpClient.send(userRequest, HttpResponse.BodyHandlers.ofString())
if (userResponse.statusCode() != 200) { ec.logger.error("Google user fetch failed: ${userResponse.body()}") success = false message = "Failed to fetch user profile from Google." errorCode = "USER_FETCH_FAILED" return }
def googleUser = new JsonSlurper().parseText(userResponse.body()) def googleUserId = googleUser.id?.toString() def googleEmail = googleUser.email def googleName = googleUser.name def googleAvatarUrl = googleUser.picture def googleGivenName = googleUser.given_name def googleFamilyName = googleUser.family_name
if (!googleEmail) { success = false message = "Could not retrieve email from Google. Please ensure your email is verified on Google." errorCode = "NO_EMAIL" return }
if (!googleUser.verified_email) { success = false message = "Your Google email is not verified. Please verify your email on Google and try again." errorCode = "EMAIL_NOT_VERIFIED" return }
ec.logger.info("Google user fetched: ${googleName} (${googleEmail})")
// Step 3: Call the user creation/linking service def createResult = ec.service.sync().name("novel.anime.NovelAnimeAuthServices.createOrLink#GoogleUser") .parameters([ googleUserId: googleUserId, email: googleEmail, username: googleName, givenName: googleGivenName, familyName: googleFamilyName, avatarUrl: googleAvatarUrl, googleAccessToken: googleAccessToken, profileData: userResponse.body() ]) .disableAuthz() .call()
if (!createResult.success) { success = false message = createResult.message errorCode = createResult.errorCode return }
// Return the results success = true accessToken = createResult.accessToken refreshToken = createResult.refreshToken expiresIn = createResult.expiresIn user = createResult.user isNewUser = createResult.isNewUser message = createResult.message
} catch (Exception e) { ec.logger.error("Google OAuth login failed", e) success = false message = "Google login failed: " + e.message errorCode = "GOOGLE_LOGIN_ERROR" }

