import java.security.SecureRandom
import java.util.Base64
import java.net.URLEncoder
import java.nio.charset.StandardCharsets

try {
    // Get WeChat OAuth configuration from environment or defaults
    def appId = System.getenv("WECHAT_APP_ID") ?: "your_wechat_app_id"
    def callbackUrl = redirectUri ?: System.getenv("WECHAT_CALLBACK_URL") ?: "http://localhost:8080/rest/s1/novel-anime/auth/oauth/wechat/callback"
    def qrcodeBaseUrl = "https://open.weixin.qq.com/connect/qrconnect"
    def scope = "snsapi_login"
    def expireSecondsConfig = System.getenv("WECHAT_QR_EXPIRE_SECONDS") ?: "600"

    // Validate configuration
    if (appId == "your_wechat_app_id") {
        success = false
        message = "WeChat OAuth is not configured. Please set WECHAT_APP_ID environment variable."
        errorCode = "OAUTH_NOT_CONFIGURED"
        return
    }

    // Generate unique ticket for this QR code session
    def random = new SecureRandom()
    def ticketBytes = new byte[16]
    random.nextBytes(ticketBytes)
    ticket = Base64.urlEncoder.withoutPadding().encodeToString(ticketBytes)

    // Store QR code session in memory (in production, use Redis or database)
    def qrSession = [
        ticket: ticket,
        status: 'waiting',
        createdTime: System.currentTimeMillis(),
        expireTime: System.currentTimeMillis() + (Integer.parseInt(expireSecondsConfig) * 1000),
        redirectUri: callbackUrl
    ]

    // Store in application context (temporary storage)
    if (!ec.web.applicationAttributes.wechatQRSessions) {
        ec.web.applicationAttributes.wechatQRSessions = [:]
    }
    ec.web.applicationAttributes.wechatQRSessions[ticket] = qrSession

    // Build WeChat QR code URL
    def params = [
        "appid=${URLEncoder.encode(appId, StandardCharsets.UTF_8)}",
        "redirect_uri=${URLEncoder.encode(callbackUrl, StandardCharsets.UTF_8)}",
        "response_type=code",
        "scope=${URLEncoder.encode(scope, StandardCharsets.UTF_8)}",
        "state=${URLEncoder.encode(ticket, StandardCharsets.UTF_8)}"
    ].join("&")

    qrcodeUrl = "${qrcodeBaseUrl}?${params}#wechat_redirect"
    expireSeconds = Integer.parseInt(expireSecondsConfig)
    success = true
    message = "WeChat QR code generated successfully."

    ec.logger.info("Generated WeChat QR code with ticket: ${ticket}")

} catch (Exception e) {
    ec.logger.error("Failed to generate WeChat QR code", e)
    success = false
    message = "Failed to generate WeChat QR code: " + e.message
    errorCode = "QR_GENERATION_ERROR"
}

try {
    // Get QR session from memory storage
    def qrSessions = ec.web.applicationAttributes.wechatQRSessions
    if (!qrSessions) {
        success = false
        status = 'expired'
        message = "QR code session not found."
        errorCode = "SESSION_NOT_FOUND"
        return
    }

    def qrSession = qrSessions[ticket]
    if (!qrSession) {
        success = false
        status = 'expired'
        message = "QR code ticket not found or expired."
        errorCode = "TICKET_NOT_FOUND"
        return
    }

    // Check if session has expired
    def currentTime = System.currentTimeMillis()
    if (currentTime > qrSession.expireTime) {
        // Clean up expired session
        qrSessions.remove(ticket)
        success = false
        status = 'expired'
        message = "QR code has expired. Please generate a new one."
        errorCode = "QR_EXPIRED"
        return
    }

    // Return current status
    status = qrSession.status
    success = true

    switch (status) {
        case 'waiting':
            message = "Waiting for WeChat scan..."
            break
        case 'scanned':
            message = "QR code scanned. Please confirm on your WeChat app."
            break
        case 'confirmed':
            // If confirmed, return the stored auth data
            if (qrSession.authData) {
                accessToken = qrSession.authData.accessToken
                refreshToken = qrSession.authData.refreshToken
                expiresIn = qrSession.authData.expiresIn
                user = qrSession.authData.user
                isNewUser = qrSession.authData.isNewUser
                message = qrSession.authData.message

                // Clean up session after successful retrieval
                qrSessions.remove(ticket)
            } else {
                message = "Login confirmed but auth data not available."
            }
            break
        case 'error':
            message = qrSession.errorMessage ?: "WeChat login failed."
            errorCode = qrSession.errorCode ?: "WECHAT_LOGIN_ERROR"
            // Clean up error session
            qrSessions.remove(ticket)
            break
        default:
            message = "Unknown status: ${status}"
            break
    }

    ec.logger.debug("WeChat login status check - Ticket: ${ticket}, Status: ${status}")

} catch (Exception e) {
    ec.logger.error("WeChat login status check failed", e)
    success = false
    status = 'error'
    message = "Status check failed: " + e.message
    errorCode = "STATUS_CHECK_ERROR"
}

import java.net.http.HttpClient import java.net.http.HttpRequest import java.net.http.HttpResponse import java.net.URI import java.nio.charset.StandardCharsets import groovy.json.JsonSlurper import groovy.json.JsonBuilder
try { // Get WeChat OAuth configuration def appId = System.getenv("WECHAT_APP_ID") ?: "your_wechat_app_id" def appSecret = System.getenv("WECHAT_APP_SECRET") ?: "your_wechat_app_secret" def tokenUrl = "https://api.weixin.qq.com/sns/oauth2/access_token" def userinfoUrl = "https://api.weixin.qq.com/sns/userinfo"
// Validate configuration if (appId == "your_wechat_app_id" || appSecret == "your_wechat_app_secret") { success = false message = "WeChat OAuth is not configured. Please set WECHAT_APP_ID and WECHAT_APP_SECRET environment variables." errorCode = "OAUTH_NOT_CONFIGURED" return }
// Step 1: Exchange authorization code for access token def httpClient = HttpClient.newBuilder() .version(HttpClient.Version.HTTP_2) .build()
def tokenRequestUrl = "${tokenUrl}?appid=${appId}&secret=${appSecret}&code=${code}&grant_type=authorization_code"
def tokenRequest = HttpRequest.newBuilder() .uri(URI.create(tokenRequestUrl)) .header("Accept", "application/json") .GET() .build()
def tokenResponse = httpClient.send(tokenRequest, HttpResponse.BodyHandlers.ofString())
if (tokenResponse.statusCode() != 200) { ec.logger.error("WeChat token exchange failed: ${tokenResponse.body()}") success = false message = "Failed to exchange authorization code. Please try again." errorCode = "TOKEN_EXCHANGE_FAILED" return }
def tokenData = new JsonSlurper().parseText(tokenResponse.body())
if (tokenData.errcode) { ec.logger.error("WeChat OAuth error: ${tokenData.errmsg ?: tokenData.errcode}") success = false message = tokenData.errmsg ?: "WeChat authorization failed." errorCode = "WECHAT_AUTH_ERROR" return }
def wechatAccessToken = tokenData.access_token def openid = tokenData.openid def unionid = tokenData.unionid // May be null for some apps
if (!wechatAccessToken || !openid) { success = false message = "No access token or openid received from WeChat." errorCode = "NO_ACCESS_TOKEN" return }
// Step 2: Fetch user profile from WeChat API def userinfoRequestUrl = "${userinfoUrl}?access_token=${wechatAccessToken}&openid=${openid}&lang=zh_CN"
def userRequest = HttpRequest.newBuilder() .uri(URI.create(userinfoRequestUrl)) .header("Accept", "application/json") .GET() .build()
def userResponse = httpClient.send(userRequest, HttpResponse.BodyHandlers.ofString())
if (userResponse.statusCode() != 200) { ec.logger.error("WeChat user fetch failed: ${userResponse.body()}") success = false message = "Failed to fetch user profile from WeChat." errorCode = "USER_FETCH_FAILED" return }
def wechatUser = new JsonSlurper().parseText(userResponse.body())
if (wechatUser.errcode) { ec.logger.error("WeChat userinfo error: ${wechatUser.errmsg ?: wechatUser.errcode}") success = false message = wechatUser.errmsg ?: "Failed to get WeChat user info." errorCode = "USERINFO_ERROR" return }
def wechatUserId = unionid ?: openid // Prefer unionid if available def wechatNickname = wechatUser.nickname def wechatAvatarUrl = wechatUser.headimgurl def wechatCountry = wechatUser.country def wechatProvince = wechatUser.province def wechatCity = wechatUser.city def wechatSex = wechatUser.sex // 1=male, 2=female, 0=unknown
ec.logger.info("WeChat user fetched: ${wechatNickname} (${openid})")
// Step 3: Call the user creation/linking service def createResult = ec.service.sync().name("novel.anime.NovelAnimeAuthServices.createOrLink#WeChatUser") .parameters([ wechatUserId: wechatUserId, openid: openid, unionid: unionid, nickname: wechatNickname, avatarUrl: wechatAvatarUrl, country: wechatCountry, province: wechatProvince, city: wechatCity, sex: wechatSex, wechatAccessToken: wechatAccessToken, profileData: userResponse.body() ]) .disableAuthz() .call()
if (!createResult.success) { success = false message = createResult.message errorCode = createResult.errorCode return }
// Return the results success = true accessToken = createResult.accessToken refreshToken = createResult.refreshToken expiresIn = createResult.expiresIn user = createResult.user isNewUser = createResult.isNewUser message = createResult.message
// Update QR session status if state (ticket) is provided if (state) { def qrSessions = ec.web.applicationAttributes.wechatQRSessions if (qrSessions && qrSessions[state]) { qrSessions[state].status = 'confirmed' qrSessions[state].authData = [ accessToken: accessToken, refreshToken: refreshToken, expiresIn: expiresIn, user: user, isNewUser: isNewUser, message: message ] } }
} catch (Exception e) { ec.logger.error("WeChat OAuth login failed", e) success = false message = "WeChat login failed: " + e.message errorCode = "WECHAT_LOGIN_ERROR"
// Update QR session status on error if (state) { def qrSessions = ec.web.applicationAttributes.wechatQRSessions if (qrSessions && qrSessions[state]) { qrSessions[state].status = 'error' qrSessions[state].errorMessage = message qrSessions[state].errorCode = errorCode } } }

import java.net.URLEncoder

// Handle error from WeChat (Requirement 2.3.3)
if (error) {
    success = false
    message = error_description ?: "WeChat authorization was denied or failed."
    errorCode = "WECHAT_AUTH_DENIED"
    redirectUrl = "novelanime://auth/error?message=${URLEncoder.encode(message, 'UTF-8')}"

    // Update QR session status on error
    if (state) {
        def qrSessions = ec.web.applicationAttributes.wechatQRSessions
        if (qrSessions && qrSessions[state]) {
            qrSessions[state].status = 'error'
            qrSessions[state].errorMessage = message
            qrSessions[state].errorCode = errorCode
        }
    }
    return
}

if (!code) {
    success = false
    message = "No authorization code received from WeChat."
    errorCode = "NO_AUTH_CODE"
    redirectUrl = "novelanime://auth/error?message=${URLEncoder.encode(message, 'UTF-8')}"

    // Update QR session status on error
    if (state) {
        def qrSessions = ec.web.applicationAttributes.wechatQRSessions
        if (qrSessions && qrSessions[state]) {
            qrSessions[state].status = 'error'
            qrSessions[state].errorMessage = message
            qrSessions[state].errorCode = errorCode
        }
    }
    return
}

// Call the main login service
def loginResult = ec.service.sync().name("novel.anime.NovelAnimeAuthServices.login#WithWeChat")
    .parameters([code: code, state: state])
    .disableAuthz()
    .call()

success = loginResult.success
accessToken = loginResult.accessToken
refreshToken = loginResult.refreshToken
expiresIn = loginResult.expiresIn
user = loginResult.user
isNewUser = loginResult.isNewUser
message = loginResult.message
errorCode = loginResult.errorCode

// Generate redirect URL for desktop app
if (success) {
    redirectUrl = "novelanime://auth/success?token=${accessToken}&refresh=${refreshToken}"
} else {
    redirectUrl = "novelanime://auth/error?message=${URLEncoder.encode(message ?: 'Login failed', 'UTF-8')}"
}

import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.Base64
import java.time.Instant
import java.nio.charset.StandardCharsets
import groovy.json.JsonBuilder

try {
    def now = ec.user.nowTimestamp
    isNewUser = false

    // Step 1: Check if OAuth account already exists (Requirement 2.3.2 - existing user)
    def existingOAuth = ec.entity.find("novel.anime.user.UserOAuthAccount")
        .condition("provider", "wechat")
        .condition("providerUserId", wechatUserId)
        .disableAuthz()
        .one()

    def userRecord = null

    if (existingOAuth) {
        // User has logged in with WeChat before - get existing user
        userRecord = ec.entity.find("novel.anime.user.NovelAnimeUser")
            .condition("userId", existingOAuth.userId)
            .disableAuthz()
            .one()

        if (!userRecord) {
            // Orphaned OAuth account - clean up and create new user
            existingOAuth.delete()
            existingOAuth = null
        } else {
            // Update OAuth account with latest token
            existingOAuth.accessToken = wechatAccessToken
            existingOAuth.profileData = profileData
            existingOAuth.lastUsedDate = now
            existingOAuth.update()

            // Update user's last login and avatar
            userRecord.lastLoginDate = now
            if (avatarUrl && !userRecord.avatarUrl) {
                userRecord.avatarUrl = avatarUrl
            }
            userRecord.update()

            userId = userRecord.userId
            ec.logger.info("Existing WeChat user logged in: ${nickname} (${openid})")
        }
    }

    if (!userRecord) {
        // Step 2: WeChat doesn't provide email, so we create a new user directly
        // (No email linking possible with WeChat)

        // Step 3: Create new user with 500 initial credits (Requirement 2.3.4)
        isNewUser = true
        userId = ec.entity.sequencedIdPrimary
        def displayName = nickname ?: "WeChat User"

        // Generate a placeholder email using openid
        def placeholderEmail = "wechat_${openid}@novelanime.local"

        // Create new user
        ec.entity.makeValue("novel.anime.user.NovelAnimeUser").setAll([
            userId: userId,
            email: placeholderEmail,
            username: displayName,
            passwordHash: null, // No password for OAuth users
            avatarUrl: avatarUrl,
            credits: 500,
            status: 'active',
            authProvider: 'wechat',
            createdDate: now,
            lastLoginDate: now
        ]).create()

        // Record initial credits transaction
        ec.entity.makeValue("novel.anime.user.CreditTransaction").setAll([
            transactionId: ec.entity.sequencedIdPrimary,
            userId: userId,
            amount: 500,
            type: 'initial',
            operationType: 'wechat_registration',
            description: 'Initial credits on WeChat registration',
            balanceAfter: 500,
            timestamp: now
        ]).create()

        // Create OAuth account link
        ec.entity.makeValue("novel.anime.user.UserOAuthAccount").setAll([
            oauthAccountId: ec.entity.sequencedIdPrimary,
            userId: userId,
            provider: "wechat",
            providerUserId: wechatUserId,
            accessToken: wechatAccessToken,
            profileData: profileData,
            createdDate: now,
            lastUsedDate: now
        ]).create()

        // Fetch the created user
        userRecord = ec.entity.find("novel.anime.user.NovelAnimeUser")
            .condition("userId", userId)
            .disableAuthz()
            .one()

        ec.logger.info("New WeChat user created: ${nickname} (${openid}) with 500 initial credits")
    }

    // Step 4: Generate JWT tokens
    def jwtSecret = "MoquiJWTSecretKey123456789012345678901234567890"
    def accessExpiryTime = Instant.now().plusSeconds(3600) // 1 hour
    def refreshExpiryTime = Instant.now().plusSeconds(604800) // 7 days

    // Create JWT Header
    def header = new JsonBuilder([
        alg: "HS256",
        typ: "JWT"
    ]).toString()

    // Create Access Token payload
    def accessPayload = new JsonBuilder([
        sub: userId,
        email: userRecord.email,
        provider: "wechat",
        iat: Instant.now().epochSecond,
        exp: accessExpiryTime.epochSecond,
        type: "access"
    ]).toString()

    // Create Refresh Token payload
    def refreshPayload = new JsonBuilder([
        sub: userId,
        iat: Instant.now().epochSecond,
        exp: refreshExpiryTime.epochSecond,
        type: "refresh"
    ]).toString()

    // Base64 encode
    def encodedHeader = Base64.urlEncoder.withoutPadding().encodeToString(header.getBytes(StandardCharsets.UTF_8))
    def encodedAccessPayload = Base64.urlEncoder.withoutPadding().encodeToString(accessPayload.getBytes(StandardCharsets.UTF_8))
    def encodedRefreshPayload = Base64.urlEncoder.withoutPadding().encodeToString(refreshPayload.getBytes(StandardCharsets.UTF_8))

    // Create signatures
    def mac = Mac.getInstance("HmacSHA256")
    def secretKey = new SecretKeySpec(jwtSecret.getBytes(StandardCharsets.UTF_8), "HmacSHA256")
    mac.init(secretKey)

    def accessTokenData = encodedHeader + "." + encodedAccessPayload
    def accessSignature = Base64.urlEncoder.withoutPadding().encodeToString(mac.doFinal(accessTokenData.getBytes(StandardCharsets.UTF_8)))

    mac.reset()
    mac.init(secretKey)
    def refreshTokenData = encodedHeader + "." + encodedRefreshPayload
    def refreshSignature = Base64.urlEncoder.withoutPadding().encodeToString(mac.doFinal(refreshTokenData.getBytes(StandardCharsets.UTF_8)))

    accessToken = accessTokenData + "." + accessSignature
    refreshToken = refreshTokenData + "." + refreshSignature
    expiresIn = 3600L

    // Build user response object
    user = [
        userId: userRecord.userId,
        email: userRecord.email,
        username: userRecord.username,
        credits: userRecord.credits,
        avatarUrl: userRecord.avatarUrl,
        authProvider: userRecord.authProvider,
        createdDate: userRecord.createdDate?.toString(),
        lastLoginDate: userRecord.lastLoginDate?.toString()
    ]

    success = true
    message = isNewUser ? "Welcome to Novel Anime! Your account has been created with 500 credits." : "WeChat login successful."

} catch (Exception e) {
    ec.logger.error("WeChat user creation/linking failed", e)
    success = false
    message = "Failed to create or link WeChat account: " + e.message
    errorCode = "USER_CREATION_ERROR"
}
